import{_ as t,c as a,o as r,ae as i}from"./chunks/framework.CliRSA9F.js";const s="/images/ratings_and_reviews.webp",p=JSON.parse('{"title":"Ratings & Reviews","description":"","frontmatter":{},"headers":[],"relativePath":"features/ratings-and-reviews.md","filePath":"features/ratings-and-reviews.md"}'),n={name:"features/ratings-and-reviews.md"};function o(l,e,g,d,h,u){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="ratings-reviews" tabindex="-1">Ratings &amp; Reviews <a class="header-anchor" href="#ratings-reviews" aria-label="Permalink to &quot;Ratings &amp; Reviews&quot;">​</a></h1><h2 id="track-listener-feedback-across-platforms" tabindex="-1">Track Listener Feedback Across Platforms <a class="header-anchor" href="#track-listener-feedback-across-platforms" aria-label="Permalink to &quot;Track Listener Feedback Across Platforms&quot;">​</a></h2><p>Ratings &amp; Reviews gives you a comprehensive view of how listeners rate and review your podcast on Apple Podcasts and Spotify. Monitor your ratings across regions, understand rating distributions, and read individual reviews to learn what resonates with your audience.</p><p><img src="'+s+'" alt="Ratings and Reviews Dashboard" width="600px" style="display:block;margin:0 auto;"></p><h2 id="what-you-ll-see" tabindex="-1">What You&#39;ll See <a class="header-anchor" href="#what-you-ll-see" aria-label="Permalink to &quot;What You&#39;ll See&quot;">​</a></h2><h3 id="listener-sentiment" tabindex="-1">Listener Sentiment <a class="header-anchor" href="#listener-sentiment" aria-label="Permalink to &quot;Listener Sentiment&quot;">​</a></h3><p>The page leads with <strong>Listener Sentiment</strong> — a single percentage showing what share of your Apple Podcasts ratings are positive (4 or 5 stars). This is the fastest read on how your audience feels about your show. Below the headline number, a sentiment strip and star legend break the percentage down across all five star levels, so you can see at a glance whether your ratings cluster at the top or spread out.</p><p>Next to your sentiment score you&#39;ll find quick totals — your total number of Apple ratings, how many storefronts (countries) you appear in, and your Spotify average when available.</p><h3 id="ratings-by-storefront" tabindex="-1">Ratings by Storefront <a class="header-anchor" href="#ratings-by-storefront" aria-label="Permalink to &quot;Ratings by Storefront&quot;">​</a></h3><p>Apple Podcasts reports ratings separately for each storefront (country), and PodSEO lists them in a per-storefront table with a flag, average star rating, and rating count for each. The table shows your first seven storefronts by default; if you appear in more, use the <strong>Show more storefronts</strong> link to reveal the rest.</p><p>Spotify reports a single combined rating, shown alongside as an average star score with its total number of ratings.</p><h3 id="rating-distribution" tabindex="-1">Rating Distribution <a class="header-anchor" href="#rating-distribution" aria-label="Permalink to &quot;Rating Distribution&quot;">​</a></h3><p>Understand how your ratings break down across the star spectrum:</p><ul><li><strong>Visual bar chart</strong> showing percentage of 1-star through 5-star ratings</li><li><strong>Positive percentage</strong> - Combined 4 and 5-star ratings as a single metric</li><li><strong>Distribution insights</strong> - See if ratings cluster around certain star levels</li></ul><h3 id="recent-trend" tabindex="-1">Recent Trend <a class="header-anchor" href="#recent-trend" aria-label="Permalink to &quot;Recent Trend&quot;">​</a></h3><p>Track how your ratings are trending over the past 7 days:</p><ul><li><strong>Daily indicators</strong> - Visual bars showing rating sentiment each day</li><li><strong>Trend direction</strong> - Positive (rising), Negative (falling), or Neutral</li><li><strong>Sparkline visualization</strong> - Quick visual of recent rating momentum</li></ul><h3 id="latest-review" tabindex="-1">Latest Review <a class="header-anchor" href="#latest-review" aria-label="Permalink to &quot;Latest Review&quot;">​</a></h3><p>A <strong>Latest Review</strong> highlight card spotlights your most recent piece of listener feedback, showing its star rating, the storefront it came from, the date, the review title, and a preview of the text. It&#39;s a quick way to see what someone just said about your show without scrolling through the full list.</p><h3 id="individual-reviews" tabindex="-1">Individual Reviews <a class="header-anchor" href="#individual-reviews" aria-label="Permalink to &quot;Individual Reviews&quot;">​</a></h3><p>Below the highlight, the <strong>Apple Reviews</strong> list shows your recent reviews, most recent first. Each review card includes:</p><ul><li><strong>Star rating</strong> - The rating the listener gave</li><li><strong>Storefront and date</strong> - Where the review came from and when it was posted</li><li><strong>Review title and content</strong> - The full text of the review</li><li><strong>Author</strong> - The listener&#39;s display name</li></ul><p>Longer reviews are trimmed to keep the list scannable. When a review runs long, click <strong>Read full review</strong> to expand it in place (and <strong>Show less</strong> to collapse it again). The list starts with your twelve most recent reviews; if you have more, the <strong>Load more</strong> button reveals additional reviews twelve at a time so you can work through your full recent history at your own pace.</p><h2 id="understanding-your-ratings" tabindex="-1">Understanding Your Ratings <a class="header-anchor" href="#understanding-your-ratings" aria-label="Permalink to &quot;Understanding Your Ratings&quot;">​</a></h2><h3 id="what-ratings-tell-you" tabindex="-1">What Ratings Tell You <a class="header-anchor" href="#what-ratings-tell-you" aria-label="Permalink to &quot;What Ratings Tell You&quot;">​</a></h3><p>Your ratings provide valuable feedback signals:</p><ul><li><strong>Overall satisfaction</strong> - High average ratings indicate listener satisfaction</li><li><strong>Consistency</strong> - Tight distribution around 4-5 stars shows consistent quality</li><li><strong>Problem areas</strong> - Clusters of low ratings may indicate specific issues to address</li><li><strong>Regional differences</strong> - Varying ratings by country can reveal market-specific preferences</li></ul><h3 id="reading-review-patterns" tabindex="-1">Reading Review Patterns <a class="header-anchor" href="#reading-review-patterns" aria-label="Permalink to &quot;Reading Review Patterns&quot;">​</a></h3><p>Look for patterns in your reviews to understand:</p><ul><li><strong>What listeners love</strong> - Common themes in positive reviews</li><li><strong>Pain points</strong> - Recurring complaints in negative reviews</li><li><strong>Content preferences</strong> - Which episodes or topics generate the most feedback</li><li><strong>Listener expectations</strong> - What your audience expects from your podcast</li></ul><h2 id="using-ratings-strategically" tabindex="-1">Using Ratings Strategically <a class="header-anchor" href="#using-ratings-strategically" aria-label="Permalink to &quot;Using Ratings Strategically&quot;">​</a></h2><h3 id="improving-your-ratings" tabindex="-1">Improving Your Ratings <a class="header-anchor" href="#improving-your-ratings" aria-label="Permalink to &quot;Improving Your Ratings&quot;">​</a></h3><p>Focus on areas that drive positive ratings:</p><ul><li><strong>Consistent quality</strong> - Maintain production standards across all episodes</li><li><strong>Listener engagement</strong> - Respond to feedback and incorporate suggestions</li><li><strong>Clear expectations</strong> - Ensure your podcast delivers what it promises</li><li><strong>Regular publishing</strong> - Consistent release schedules build listener trust</li></ul><h3 id="responding-to-feedback" tabindex="-1">Responding to Feedback <a class="header-anchor" href="#responding-to-feedback" aria-label="Permalink to &quot;Responding to Feedback&quot;">​</a></h3><p>Use review insights to improve your podcast:</p><ul><li><strong>Address common complaints</strong> - If multiple reviews mention the same issue, prioritize fixing it</li><li><strong>Double down on strengths</strong> - Emphasize what listeners praise in future content</li><li><strong>Engage your community</strong> - Thank listeners for positive reviews and acknowledge feedback</li><li><strong>Track changes</strong> - Monitor if improvements lead to better ratings over time</li></ul><h2 id="regional-considerations" tabindex="-1">Regional Considerations <a class="header-anchor" href="#regional-considerations" aria-label="Permalink to &quot;Regional Considerations&quot;">​</a></h2><p>Apple Podcasts provides ratings by storefront (country), allowing you to:</p><ul><li><strong>Identify strong markets</strong> - See where your podcast resonates most</li><li><strong>Spot opportunities</strong> - Find regions where ratings could improve</li><li><strong>Tailor content</strong> - Consider regional preferences for certain topics or styles</li><li><strong>Expand strategically</strong> - Focus growth efforts on markets with positive reception</li></ul><h2 id="integration-with-other-features" tabindex="-1">Integration with Other Features <a class="header-anchor" href="#integration-with-other-features" aria-label="Permalink to &quot;Integration with Other Features&quot;">​</a></h2><p>Ratings &amp; Reviews connects with your broader podcast strategy:</p><ul><li><strong>Command Center</strong> - Tasks may suggest improvements based on rating patterns</li><li><strong>Planner</strong> - Low ratings in certain areas may indicate content optimization opportunities</li><li><strong>Competitor Analysis</strong> - Correlate rating changes with specific episodes or events</li></ul><h2 id="availability" tabindex="-1">Availability <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;Availability&quot;">​</a></h2><p>Ratings &amp; Reviews is available to all users. Rating data updates regularly as platforms report new ratings and reviews.</p><p><strong>Related Features</strong>: Check the <a href="/features/podcast-details.html">Overview</a> tab for your overall podcast metrics, and use <a href="/features/command-center.html">Command Center</a> to find actionable improvements that can boost listener satisfaction.</p>',46)])])}const m=t(n,[["render",o]]);export{p as __pageData,m as default};
